  if(r.incG)al.push('🔴 '+r.incG+(r.incG>1?' incidencias graves':' incidencia grave')+' sin resolver');if(r.err)al.push('🧾 '+r.err+(r.err>1?' actas':' acta')+' con números que no cuadran');
  if(!waNum())al.push('⚙️ Falta poner el WhatsApp de la sala de guerra en Ajustes');
